begin;create extension if not exists pgtap with schema extensions;select extensions.plan(18);
select extensions.has_table('public','twitter_item_holds','holds individuais existem');
select extensions.has_table('public','twitter_publication_attempts','tentativas X existem');
select extensions.has_table('public','twitter_operation_logs','logs X existem');
select extensions.has_function('public','twitter_claim_publication_items',array['text','integer'],'claim X existe');
select extensions.ok(not has_function_privilege('authenticated','public.twitter_claim_publication_items(text,integer)','EXECUTE'),'authenticated não reivindica fila');
select extensions.ok(has_function_privilege('service_role','public.twitter_claim_publication_items(text,integer)','EXECUTE'),'service role reivindica fila');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values('12900000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','twitter-229@example.com','',now(),now(),now());
insert into public.organizations(id,name,slug,created_by)values('22900000-0000-4000-8000-000000000001','Twitter 229','twitter-229','12900000-0000-4000-8000-000000000001');
insert into public.organization_members(organization_id,user_id,role,invited_by)values('22900000-0000-4000-8000-000000000001','12900000-0000-4000-8000-000000000001','admin','12900000-0000-4000-8000-000000000001');
create temporary table twitter_229_context(identity_id uuid,connection_id uuid,profile_id uuid,epoch_id uuid,program_id uuid,reservation_id uuid,attempt_id uuid)on commit drop;grant select,insert,update on twitter_229_context to service_role;insert into twitter_229_context default values;
set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
do $$declare identity jsonb;connection jsonb;profile jsonb;reservation jsonb;pid uuid:=gen_random_uuid();begin identity:=public.twitter_register_identity_and_grant('22900000-0000-4000-8000-000000000001','zernio-229');connection:=public.twitter_upsert_connection_credentials('22900000-0000-4000-8000-000000000001',(identity->>'identityId')::uuid,'C','zp-229',repeat('encrypted',5),repeat('e',64),'api','scope','12900000-0000-4000-8000-000000000001','twitter-229@example.com');profile:=public.twitter_sync_profile_from_zernio('22900000-0000-4000-8000-000000000001',(connection->>'connectionId')::uuid,'za-229','xu-229','perfil229','Perfil',null,true,false,true,false,'free','[]');insert into public.twitter_programs(id,organization_id,schedule_kind,starts_at,ends_at,interval_minutes,total_requested,funded_count,unfunded_count,reserved_micros,rate_card_id,rate_card_version,review_digest,idempotency_key,created_by)select pid,'22900000-0000-4000-8000-000000000001','interval',now()-interval '2 minutes',now()-interval '1 minute',1,2,2,0,30000,id,version,repeat('a',64),'program-229','12900000-0000-4000-8000-000000000001'from public.twitter_rate_cards where active;reservation:=public.twitter_create_wallet_reservation('22900000-0000-4000-8000-000000000001',(identity->>'identityId')::uuid,(connection->>'connectionId')::uuid,1,'post_dm_create','publication',pid,30000,1,'reservation-229');insert into public.twitter_program_reservations values(pid,(reservation->>'reservationId')::uuid,(identity->>'identityId')::uuid,'post_dm_create');update twitter_229_context set identity_id=(identity->>'identityId')::uuid,connection_id=(connection->>'connectionId')::uuid,profile_id=(profile->>'profileId')::uuid,epoch_id=(profile->>'epochId')::uuid,program_id=pid,reservation_id=(reservation->>'reservationId')::uuid;end$$;
insert into public.twitter_publication_items(organization_id,program_id,profile_id,connection_epoch_id,connection_id,identity_id,slot_index,execute_at,content,weighted_characters,category,amount_micros,idempotency_key)select '22900000-0000-4000-8000-000000000001',program_id,profile_id,epoch_id,connection_id,identity_id,x,now()-interval '1 minute','shadow',6,'post_dm_create',15000,'item-229-'||x from twitter_229_context cross join generate_series(0,1)x;
select extensions.is((select count(*)::bigint from public.twitter_item_holds),2::bigint,'trigger cria hold por item');
create temporary table twitter_229_claim as select * from public.twitter_claim_publication_items('shadow-worker-229',10);grant select on twitter_229_claim to service_role;
select extensions.is((select count(*)::bigint from twitter_229_claim),1::bigint,'claim retorna no máximo um item por perfil');
select extensions.is((select count(*)::bigint from public.twitter_publication_attempts),1::bigint,'claim cria uma tentativa idempotente');
select extensions.is((select status::text from public.twitter_item_holds where item_id=(select item_id from twitter_229_claim)),'active','claim ativa hold individual');
update twitter_229_context set attempt_id=(select attempt_id from twitter_229_claim);
select public.twitter_complete_shadow_attempt((select attempt_id from twitter_229_context),'shadow-release-229');
select extensions.is((select count(*)::bigint from public.twitter_publication_items where status='shadowed'),1::bigint,'shadow conclui sem publicar');
select extensions.is((select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from twitter_229_context)),15000::bigint,'shadow devolve somente seu hold');
select extensions.is((select count(*)::bigint from public.twitter_operation_logs where phase='shadow'),1::bigint,'shadow gera log financeiro');
select extensions.throws_ok($$update public.twitter_operation_logs set message='alterado'$$,'55000','Registro financeiro imutável.','log X é imutável');
select public.twitter_cancel_items('22900000-0000-4000-8000-000000000001',(select program_id from twitter_229_context),null,'cancelamento de teste','cancel-229');
select extensions.is((select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from twitter_229_context)),0::bigint,'cancelamento devolve reserva restante');
select public.twitter_cancel_items('22900000-0000-4000-8000-000000000001',(select program_id from twitter_229_context),null,'replay cancelamento','cancel-229');
select extensions.is((select count(*)::bigint from public.twitter_reservation_events where idempotency_key like 'cancel-229:%'),1::bigint,'replay não duplica devolução');
select public.twitter_record_worker_heartbeat('athena-twitter-publication-worker','worker-229','shadow','{}');
select extensions.is((select mode from public.twitter_worker_heartbeats where worker_name='athena-twitter-publication-worker'),'shadow','heartbeat X é independente');
select extensions.is((select count(*)::bigint from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_class f on f.oid=c.confrelid where t.relname like 'twitter_%'and f.relname in('instagram_profiles','publication_items')),0::bigint,'operações X não referenciam Instagram');
select jsonb_build_object('finish',(select jsonb_agg(v)from extensions.finish()v),'holds',(select count(*)from public.twitter_item_holds),'walletReserved',(select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from twitter_229_context)))diagnostics;rollback;
